composition.definitions:
open Filter

def IsSidon (S : Set Nat) : Prop :=
  ∀ a b c d : Nat, a ∈ S → b ∈ S → c ∈ S → d ∈ S →
    a + b = c + d → (a = c ∧ b = d ∨ a = d ∧ b = c)

def IsGreedy (A : Set Nat) : Prop :=
  1 ∈ A ∧ ∀ m : Nat, m ≥ 2 → m ∉ A → ¬ IsSidon (insert m A)

def greedySidon : Set Nat :=
  Classical.epsilon (fun A : Set Nat => IsSidon A ∧ IsGreedy A)

def sidonCount (N : Nat) : Nat :=
  (Finset.filter (fun (n : Nat) => n ∈ greedySidon) (Finset.Icc 1 N)).card

